import { toggleNotifications } from '@/app/actions'
import { getNotificationsEnabled } from '@/app/preferences'

export default async function Home() {
  const enabled = await getNotificationsEnabled()

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are <strong>{enabled ? 'on' : 'off'}</strong>.
      </p>
      <form action={toggleNotifications}>
        <button type="submit">{enabled ? 'Turn off' : 'Turn on'}</button>
      </form>
    </main>
  )
}

